#include "NvsLowerTankPumpProtectionStore.h"
#include <string.h>
namespace HWC { namespace {
static const uint32_t RECORD_MAGIC=0x484C5053UL, SLOT_MAGIC=0x484C5054UL;
static const uint16_t RECORD_VERSION=1, SLOT_VERSION=1;
struct Payload { uint32_t magic; uint16_t version; LowerTankPumpConfig config; uint8_t criticalLatch; uint8_t stateValid; uint32_t checksum; };
struct Slot { uint32_t magic; uint16_t version; uint16_t payloadSize; uint32_t generation; Payload payload; uint32_t checksum; };
uint32_t crcByte(uint32_t c,uint8_t b){c^=b;for(uint8_t i=0;i<8;++i){const uint32_t m=static_cast<uint32_t>(-(static_cast<int32_t>(c&1U)));c=(c>>1)^(0xEDB88320UL&m);}return c;}
template<typename T> uint32_t crcValue(uint32_t c,const T& v){const uint8_t* p=reinterpret_cast<const uint8_t*>(&v);for(size_t i=0;i<sizeof(T);++i)c=crcByte(c,p[i]);return c;}
uint32_t payloadChecksum(const Payload& p){uint32_t c=0xFFFFFFFFUL;c=crcValue(c,p.magic);c=crcValue(c,p.version);c=crcValue(c,p.config.magic);c=crcValue(c,p.config.version);c=crcValue(c,p.config.minimumLevelCm);c=crcValue(c,p.config.hysteresisCm);c=crcValue(c,p.config.checksum);c=crcValue(c,p.criticalLatch);c=crcValue(c,p.stateValid);return c^0xFFFFFFFFUL;}
bool payloadValid(const Payload& p){return p.magic==RECORD_MAGIC&&p.version==RECORD_VERSION&&p.criticalLatch<=1&&p.stateValid==1&&isLowerTankPumpConfigValid(p.config)&&lowerTankPumpConfigChecksumMatches(p.config)&&p.checksum==payloadChecksum(p);}
uint32_t slotChecksum(const Slot& s){uint32_t c=0xFFFFFFFFUL;c=crcValue(c,s.magic);c=crcValue(c,s.version);c=crcValue(c,s.payloadSize);c=crcValue(c,s.generation);c=crcValue(c,s.payload.magic);c=crcValue(c,s.payload.version);c=crcValue(c,s.payload.config.magic);c=crcValue(c,s.payload.config.version);c=crcValue(c,s.payload.config.minimumLevelCm);c=crcValue(c,s.payload.config.hysteresisCm);c=crcValue(c,s.payload.config.checksum);c=crcValue(c,s.payload.criticalLatch);c=crcValue(c,s.payload.stateValid);c=crcValue(c,s.payload.checksum);return c^0xFFFFFFFFUL;}
bool samePayload(const Payload&a,const Payload&b){return a.magic==b.magic&&a.version==b.version&&a.config.magic==b.config.magic&&a.config.version==b.config.version&&a.config.minimumLevelCm==b.config.minimumLevelCm&&a.config.hysteresisCm==b.config.hysteresisCm&&a.config.checksum==b.config.checksum&&a.criticalLatch==b.criticalLatch&&a.stateValid==b.stateValid&&a.checksum==b.checksum;}
bool validSlot(const Slot&s){return s.magic==SLOT_MAGIC&&s.version==SLOT_VERSION&&s.payloadSize==sizeof(Payload)&&s.generation!=0&&payloadValid(s.payload)&&s.checksum==slotChecksum(s);}
enum Status{ABSENT,VALID,CORRUPT};
Status readSlot(Preferences&p,const char*k,Slot&s){if(!p.isKey(k))return ABSENT;if(p.getBytesLength(k)!=sizeof(s)||p.getBytes(k,&s,sizeof(s))!=sizeof(s)||!validSlot(s))return CORRUPT;return VALID;}
bool writeSlot(Preferences&p,const char*k,const Payload&payload,uint32_t generation){Slot s={};s.magic=SLOT_MAGIC;s.version=SLOT_VERSION;s.payloadSize=sizeof(Payload);s.generation=generation;s.payload=payload;s.checksum=slotChecksum(s);if(p.putBytes(k,&s,sizeof(s))!=sizeof(s))return false;Slot check={};return readSlot(p,k,check)==VALID&&check.generation==generation&&samePayload(check.payload,payload);}
bool adjacent(uint32_t a,uint32_t b){return(a>b&&(a-b)==1U)||(b>a&&(b-a)==1U);}
}
NvsLowerTankPumpProtectionStore::NvsLowerTankPumpProtectionStore(const char*n):nameSpace_(n),opened_(false){}
bool NvsLowerTankPumpProtectionStore::begin(){if(opened_)return true;opened_=nameSpace_&&nameSpace_[0]&&preferences_.begin(nameSpace_,false);return opened_;}
void NvsLowerTankPumpProtectionStore::end(){if(opened_)preferences_.end();opened_=false;}
bool NvsLowerTankPumpProtectionStore::hasRecord(){return opened_&&(preferences_.isKey("slot0")||preferences_.isKey("slot1"));}
bool NvsLowerTankPumpProtectionStore::load(LowerTankPumpConfig&config,bool&latch,bool&stateValid){if(!opened_)return false;Slot a={},b={};Status sa=readSlot(preferences_,"slot0",a),sb=readSlot(preferences_,"slot1",b);if(sa==CORRUPT||sb==CORRUPT)return false;if(sa==ABSENT&&sb==ABSENT)return false;const Payload*p=nullptr;if(sa==VALID&&sb==VALID){if(!adjacent(a.generation,b.generation))return false;p=a.generation>b.generation?&a.payload:&b.payload;}else p=sa==VALID?&a.payload:&b.payload;config=p->config;latch=p->criticalLatch!=0;stateValid=p->stateValid==1;return stateValid;}
bool NvsLowerTankPumpProtectionStore::save(const LowerTankPumpConfig&config,bool latch,bool stateValid){if(!opened_||!stateValid||!isLowerTankPumpConfigValid(config)||!lowerTankPumpConfigChecksumMatches(config))return false;if(hasRecord()){LowerTankPumpConfig old={};bool oldLatch=false,oldValid=false;if(!load(old,oldLatch,oldValid))return false;}Payload p={};p.magic=RECORD_MAGIC;p.version=RECORD_VERSION;p.config=config;p.criticalLatch=latch?1U:0U;p.stateValid=1;p.checksum=payloadChecksum(p);Slot a={},b={};Status sa=readSlot(preferences_,"slot0",a),sb=readSlot(preferences_,"slot1",b);if(sa==CORRUPT||sb==CORRUPT)return false;const char*target="slot0";uint32_t generation=1;if(sa==VALID&&sb==VALID){bool aNew=a.generation>b.generation;const Slot&n=aNew?a:b;generation=n.generation+1U;if(!generation)return false;target=aNew?"slot1":"slot0";}else if(sa==VALID){generation=a.generation+1U;if(!generation)return false;target="slot1";}else if(sb==VALID){generation=b.generation+1U;if(!generation)return false;target="slot0";}return writeSlot(preferences_,target,p,generation);}
bool NvsLowerTankPumpProtectionStore::saveCriticalLatch(bool latch){LowerTankPumpConfig c={};bool old=false,valid=false;if(!load(c,old,valid))return false;return save(c,latch,valid);}
}
